ALTER TABLE "document_versions" ADD COLUMN "status" text DEFAULT 'in_review' NOT NULL;--> statement-breakpoint
ALTER TABLE "document_versions" ADD COLUMN "reviewed_by_collaborator_id" uuid;--> statement-breakpoint
ALTER TABLE "document_versions" ADD COLUMN "reviewed_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "document_versions" ADD COLUMN "rejection_reason" text;--> statement-breakpoint
ALTER TABLE "document_versions" ADD CONSTRAINT "document_versions_status_check" CHECK ("document_versions"."status" in ('in_review', 'approved', 'rejected'));--> statement-breakpoint
ALTER TABLE "document_versions" ADD CONSTRAINT "document_versions_review_metadata_check" CHECK (("document_versions"."status" = 'in_review' AND "document_versions"."reviewed_by_collaborator_id" IS NULL AND "document_versions"."reviewed_at" IS NULL AND "document_versions"."rejection_reason" IS NULL) OR ("document_versions"."status" = 'approved' AND "document_versions"."reviewed_by_collaborator_id" IS NOT NULL AND "document_versions"."reviewed_at" IS NOT NULL AND "document_versions"."rejection_reason" IS NULL) OR ("document_versions"."status" = 'rejected' AND "document_versions"."reviewed_by_collaborator_id" IS NOT NULL AND "document_versions"."reviewed_at" IS NOT NULL AND "document_versions"."rejection_reason" IS NOT NULL AND length(btrim("document_versions"."rejection_reason")) > 0));